#!/usr/bin/env node
// Generate realtime event artefacts from specs/contracts/realtime/events.yaml.
// Outputs:
//   - apps/web/src/shared/realtime/generated/events.ts (typed map for frontend)
//   - apps/api/src/Throne.Realtime.Contracts/Generated/RealtimeEventNames.g.cs (C# constants)
// Source of truth lives in specs/contracts/realtime/events.yaml. Do not edit generated files.

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { parse as parseYaml } from "yaml";

const __dirname = dirname(fileURLToPath(import.meta.url));
const WEB_DIR = resolve(__dirname, "..");
const ROOT_DIR = resolve(WEB_DIR, "../..");
const EVENTS_YAML = resolve(ROOT_DIR, "specs/contracts/realtime/events.yaml");
const TS_OUT = resolve(WEB_DIR, "src/shared/realtime/generated/events.ts");
const CS_OUT = resolve(
  ROOT_DIR,
  "apps/api/src/Throne.Realtime.Contracts/Generated/RealtimeEventNames.g.cs"
);

function toRepoRelative(path) {
  return path.replace(ROOT_DIR + "/", "");
}

function pascalCase(name) {
  // intent.created -> IntentCreated
  return name
    .split(/[._-]/)
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join("");
}

function constName(name) {
  // intent.created -> IntentCreated
  return pascalCase(name);
}

function tsConstName(name) {
  // intent.created -> intentCreated
  const p = pascalCase(name);
  return p.charAt(0).toLowerCase() + p.slice(1);
}

function loadEvents() {
  const doc = parseYaml(readFileSync(EVENTS_YAML, "utf8"));
  const events = doc.events ?? {};
  const ordered = Object.entries(events).sort(([a], [b]) => a.localeCompare(b));
  for (const [name, entry] of ordered) {
    if (!entry.payload && !entry.payload_ref) {
      throw new Error(`Event '${name}' is missing payload or payload_ref`);
    }
  }
  return ordered;
}

function tsBanner() {
  return [
    "// <auto-generated/>",
    "// This file is generated. Do not edit manually.",
    `// Source of truth: ${toRepoRelative(EVENTS_YAML)}`,
    "// Regenerate via: scripts/quality/codegen-frontend.sh",
    ""
  ].join("\n");
}

function csBanner() {
  return [
    "// <auto-generated/>",
    "// This file is generated. Do not edit manually.",
    `// Source of truth: ${toRepoRelative(EVENTS_YAML)}`,
    "// Regenerate via: scripts/quality/codegen-frontend.sh",
    ""
  ].join("\n");
}

function moduleAlias(moduleName) {
  // intents -> IntentsComponents
  return (
    moduleName.charAt(0).toUpperCase() + moduleName.slice(1) + "Components"
  );
}

function generateTs(events) {
  const lines = [tsBanner()];

  const refModules = new Set();
  const payloadEntries = [];
  for (const [name, entry] of events) {
    let payloadType;
    if (entry.payload_ref) {
      const m = /^([a-z][a-z0-9_-]*)#\/components\/schemas\/(.+)$/.exec(
        entry.payload_ref
      );
      if (!m) {
        throw new Error(
          `Unsupported payload_ref for ${name}: ${entry.payload_ref}`
        );
      }
      const [, mod, schema] = m;
      refModules.add(mod);
      payloadType = `${moduleAlias(mod)}["schemas"]["${schema}"]`;
    } else {
      payloadType = inlineTsType(entry.payload);
    }
    payloadEntries.push([name, payloadType]);
  }

  for (const mod of [...refModules].sort()) {
    lines.push(
      `import type { components as ${moduleAlias(mod)} } from "@/shared/api/generated/${mod}/types";`
    );
  }
  if (refModules.size > 0) {
    lines.push("");
  }

  lines.push("");
  lines.push("/** Discriminated payload type for each realtime event name. */");
  lines.push("export interface RealtimeEventMap {");
  for (const [name, payloadType] of payloadEntries) {
    lines.push(`  "${name}": ${payloadType};`);
  }
  lines.push("}");
  lines.push("");
  lines.push("export type RealtimeEventName = keyof RealtimeEventMap;");
  lines.push("");
  lines.push(
    "export const realtimeEventNames: readonly RealtimeEventName[] = ["
  );
  for (const [name] of events) {
    lines.push(`  "${name}",`);
  }
  lines.push("] as const;");
  lines.push("");
  lines.push("/** Strongly-typed envelope as delivered over SSE. */");
  lines.push(
    "export type RealtimeEventEnvelope<K extends RealtimeEventName = RealtimeEventName> = {"
  );
  lines.push("  [P in K]: { name: P; payload: RealtimeEventMap[P] };");
  lines.push("}[K];");
  lines.push("");
  return lines.join("\n");
}

function inlineTsType(schema) {
  if (!schema || schema.type !== "object" || !schema.properties) {
    return "unknown";
  }
  const required = new Set(schema.required ?? []);
  const fields = Object.entries(schema.properties).map(([k, v]) => {
    const optional = required.has(k) ? "" : "?";
    const t =
      v.type === "string"
        ? "string"
        : v.type === "integer"
          ? "number"
          : "unknown";
    return `${k}${optional}: ${t}`;
  });
  return `{ ${fields.join("; ")} }`;
}

function generateCs(events) {
  const lines = [csBanner()];
  lines.push("namespace Throne.Realtime.Contracts.Generated;");
  lines.push("");
  lines.push("/// <summary>");
  lines.push("/// Canonical names of all server-to-client realtime events.");
  lines.push("/// Generated from specs/contracts/realtime/events.yaml.");
  lines.push("/// </summary>");
  lines.push("public static class RealtimeEventNames");
  lines.push("{");
  for (const [name] of events) {
    lines.push(`    public const string ${constName(name)} = "${name}";`);
  }
  lines.push("");
  lines.push(
    "    public static readonly System.Collections.Generic.IReadOnlyList<string> All = new[]"
  );
  lines.push("    {");
  for (const [name] of events) {
    lines.push(`        ${constName(name)},`);
  }
  lines.push("    };");
  lines.push("}");
  lines.push("");
  return lines.join("\n");
}

function main() {
  const events = loadEvents();
  if (events.length === 0) {
    console.log(`No realtime events found in ${EVENTS_YAML}`);
    return;
  }

  mkdirSync(dirname(TS_OUT), { recursive: true });
  writeFileSync(TS_OUT, generateTs(events));

  mkdirSync(dirname(CS_OUT), { recursive: true });
  writeFileSync(CS_OUT, generateCs(events));

  console.log(`Realtime codegen complete (${String(events.length)} events).`);
}

main();
